<script setup lang="ts">
import RosterPanel from '../components/RosterPanel.vue'
import { ref,computed } from 'vue'
import { useRoute } from 'vue-router'
import { usePlatform } from '../stores/platform'
import type { Session } from '../domain/types'
import PageHead from '../components/PageHead.vue'
import Icon from '../components/Icon.vue'
import Badge from '../components/Badge.vue'
import Modal from '../components/Modal.vue'
const s=usePlatform(),route=useRoute(),monitor=computed(()=>route.params.page==='monitor');const open=ref(false),assign=ref<Session|null>(null),roster=ref<Session|null>(null),paperId=ref(''),selectedSession=ref('EXAM-001'),search=ref(''),eventModal=ref(false)
const form=ref<Omit<Session,'id'>>({name:'',paperId:'',venue:'集团培训中心',room:'第二机考室',date:'2026-09-28T09:00',status:'待配卷',candidates:30,duration:90,proctor:'赵敏',elapsedOffset:0})
const sessions=computed(()=>s.data.sessions.filter(e=>!search.value||e.name.includes(search.value)))
const attempts=computed(()=>s.data.attempts.filter(a=>a.sessionId===selectedSession.value));const activeSession=computed(()=>s.data.sessions.find(e=>e.id===selectedSession.value))
const members=computed(()=>s.data.continuity!.enrollments.filter(e=>e.sessionId===selectedSession.value).sort((a,b)=>a.seat-b.seat))
function seatStatus(personId:string){return attempts.value.find(a=>a.personId===personId)?.status||'待入场'}
function create(){s.run(()=>{s.saveSession(form.value);open.value=false})}
function assigned(){s.run(()=>{s.assignPaper(assign.value!.id,paperId.value);assign.value=null})}
</script>
<template><PageHead :title="monitor?'考场实时监控':'考试组织'" :subtitle="monitor?'关注考试进度与异常事件，处置过程统一记录。':'安排场次、配发试卷、分配监考，连接题库资源与考生考试。'" eyebrow="考试与评价 / 考务管理"><RouterLink class="button" to="/protocol/examination">考试管控配置</RouterLink><button v-if="!monitor" class="button primary" @click="open=true"><Icon name="Plus" :size="17"/>新建考试场次</button><button v-else class="button" @click="eventModal=true"><Icon name="ShieldAlert" :size="16"/>异常事件记录</button></PageHead>
<template v-if="!monitor"><div class="mini-metrics"><div><span>考试场次</span><strong>{{s.data.sessions.length}} <small>场</small></strong></div><div><span>已配发试卷</span><strong>{{s.data.sessions.filter(e=>e.paperId).length}} <small>场</small></strong></div><div><span>计划考生</span><strong>{{s.data.sessions.reduce((a,e)=>a+e.candidates,0)}} <small>人</small></strong></div><div><span>实际演示答卷</span><strong>{{s.data.attempts.length}} <small>份</small></strong></div></div><section class="panel"><div class="filter-bar"><div class="input-icon"><Icon name="Search" :size="16"/><input v-model="search" placeholder="搜索考试场次…"/></div><span class="filter-meta">原考务对接为模拟数据</span></div><div class="table-scroll"><table><thead><tr><th>考试场次</th><th>考点 / 考场</th><th>人数 / 时长</th><th>监考人员</th><th>状态</th><th>试卷</th><th>操作</th></tr></thead><tbody><tr v-for="e in sessions"><td><strong class="cell-title">{{e.name}}</strong><small>{{e.date.replace('T',' ')}} · {{e.id}}</small></td><td>{{e.venue}}<small>{{e.room}}</small></td><td>{{e.candidates}}人<small>{{e.duration}}分钟</small></td><td>{{e.proctor}}</td><td><Badge :text="e.status"/></td><td>{{e.paperId?'已配发':'待配发'}}</td><td><div class="action-group"><button class="text-button" @click="assign=e;paperId=e.paperId">配卷</button><button class="text-button" @click="roster=e">考生 / 机位</button></div></td></tr></tbody></table></div></section><div class="notice spaced">报名、资格审查、证书管理属于原系统边界待确认项。本演示聚焦本次升级所需的场次、考场、配卷与考试衔接。</div></template>
<template v-else><div class="filter-bar panel"><label class="inline-label">当前场次<select v-model="selectedSession"><option v-for="e in s.data.sessions" :value="e.id">{{e.name}}</option></select></label><span class="live-indicator"><i></i>本地状态联动</span></div><div class="metric-grid monitor-metrics"><div class="metric-card" v-for="c in [{label:'计划考生',value:activeSession?.candidates||0,color:'blue',icon:'Users'},{label:'实际在考',value:attempts.filter(a=>a.status==='在考').length,color:'teal',icon:'Monitor'},{label:'已交卷',value:attempts.filter(a=>a.status!=='在考').length,color:'violet',icon:'CircleCheck'},{label:'异常事件',value:attempts.reduce((n,a)=>n+a.events.length,0),color:'orange',icon:'ShieldAlert'}]"><div class="metric-top"><span>{{c.label}}</span><span class="metric-icon" :class="c.color"><Icon :name="c.icon"/></span></div><div class="metric-value">{{c.value}}</div></div></div><section class="panel"><div class="panel-head"><h3>{{activeSession?.room}} · 机位视图</h3><span class="subtle-label">按本场名单与实际答卷关联</span></div><div class="seat-grid"><div v-for="member in members" class="seat" :class="seatStatus(member.personId)==='在考'?'in-exam':seatStatus(member.personId)==='待入场'?'':'submitted'"><Icon name="Monitor" :size="27"/><strong>{{String(member.seat).padStart(2,'0')}}号机位</strong><span>{{member.name}}</span><span>{{seatStatus(member.personId)}}</span></div></div></section><section v-if="attempts.length" class="panel spaced"><div class="panel-head"><h3>实际演示答卷</h3></div><table><thead><tr><th>考生</th><th>答题进度</th><th>状态</th><th>异常</th><th>操作</th></tr></thead><tbody><tr v-for="a in attempts"><td>{{a.candidate}}</td><td>{{Object.keys(a.answers).length}} / {{a.questions.length}}</td><td><Badge :text="a.status"/></td><td>{{a.events.length}}条</td><td><button class="text-button" @click="eventModal=true">查看记录</button></td></tr></tbody></table></section><div class="notice spaced">人脸、IP、摄像头与系统级防舞弊未接入。此处演示考试业务状态和浏览器事件，不代表真实安全防护。</div></template>
<Modal v-if="open" title="新建考试场次" wide @close="open=false"><div class="form-grid"><label class="span-two">考试名称<input v-model="form.name" placeholder="输入本次认定考试名称"/></label><label>考试时间<input v-model="form.date" type="datetime-local"/></label><label>考试时长（分钟）<input v-model.number="form.duration" type="number" min="15"/></label><label>考点<input v-model="form.venue"/></label><label>考场<input v-model="form.room"/></label><label>考生人数<input v-model.number="form.candidates" type="number" min="1" max="2000"/></label><label>监考人员<select v-model="form.proctor"><option v-for="e in s.data.experts">{{e.name}}</option></select></label></div><template #footer><button class="button" @click="open=false">取消</button><button class="button primary" @click="create">创建场次</button></template></Modal>
<Modal v-if="assign" title="配发考试试卷" @close="assign=null"><h3>{{assign.name}}</h3><label class="field">选择已冻结试卷<select v-model="paperId"><option value="">请选择</option><option v-for="p in s.data.papers.filter(p=>['已冻结','已配发'].includes(p.status))" :value="p.id">{{p.name}} · V{{p.version}}</option></select></label><div class="notice">配发后，考生可在对应场次进入考试。已有答卷的场次不可替换试卷。</div><template #footer><button class="button primary" @click="assigned">确认配发并发布</button></template></Modal>
<Modal v-if="roster" title="考生名单与机位编排" wide @close="roster=null"><RosterPanel :key="roster.id" :session-id="roster.id"/></Modal>
<Modal v-if="eventModal" title="考试异常与处置记录" wide @close="eventModal=false"><div v-for="a in attempts" class="event-list"><h4>{{a.candidate}} · {{a.id}}</h4><p v-for="(e,i) in a.events"><Icon name="CircleAlert" :size="16"/>{{e}}<button v-if="!e.includes('已复核')" class="text-button" @click="a.events[i]+=' [已复核]';s.audit('监考管理','复核异常',a.id)">标记已复核</button></p><p v-if="!a.events.length" class="muted">该答卷暂无异常。</p></div><p v-if="!attempts.length" class="muted">尚无实际演示答卷。先切换考生角色参加考试。</p></Modal>
</template>
